#include <iostream>
#include <vector>
using namespace std;

vector<int> input_numbers() {
    vector<int> nums(2);
    cin >> nums[0] >> nums[1];
    return nums;
}

long long mod_pow(long long base, long long exponent, long long modulus) {
    long long total = 1;
    base %= modulus;
    while (exponent > 0) {
        if (exponent % 2 != 0) {
            total = (total * base) % modulus;
        }
        base = (base * base) % modulus;
        exponent /= 2;
    }
    return total;
}

int main() {
    vector<int> input = input_numbers();
    int p = input[0], k = input[1];
    const long long MOD = 1000000007;
    long long res = 0;

    if (k == 0) {
        res = mod_pow(p, p - 1, MOD);
    } else {
        for (int i = 1; i < p; ++i) {
            if ((p - 1) % i == 0 && mod_pow(k, i, p) == 1) {
                res = mod_pow(p, (p - 1) / i, MOD);
                if (k == 1) {
                    res = (res * p) % MOD;
                }
                break;
            }
        }
    }
    cout << res << endl;
    return 0;
}
